"""Publish a dated, offline-readable paper-trading snapshot; not runtime state."""
import argparse, json, html, hashlib
from pathlib import Path
from datetime import datetime,timezone
p=argparse.ArgumentParser();p.add_argument('--source',required=True);a=p.parse_args();src=Path(a.source).resolve();repo=Path(__file__).resolve().parent.parent
out=repo/'experimentos/noticias';out.mkdir(parents=True,exist_ok=True)
runs={key:json.loads((src/file).read_text()) for key,file in {'breakout':'web/data/news-filter-v1.json','g151':'web/data/g151-news-filter-v1.json'}.items()}
at=datetime.now(timezone.utc).isoformat();data={'snapshotAt':at,'mode':'static_snapshot_paper_only','runs':runs,'verification':{'nodeTestsPassed':213,'g151ModelParity':runs['g151']['registration']['modelVerification']},'codeManifestSHA256':hashlib.sha256((repo/'app/source-manifest.json').read_bytes()).hexdigest()}
(out/'snapshot.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
e=html.escape
def date(ms):return datetime.fromtimestamp(ms/1000,timezone.utc).isoformat()
def brl(v):return 'R$ '+f'{v:,.2f}'
rows=[];notes=[]
for key,r in runs.items():
 name='G1515m' if key=='g151' else 'Rompimento1h';p=r['registration']['protocol']
 for s in r.get('scenarios',[]):rows.append('<tr>'+''.join('<td>'+e(str(x))+'</td>' for x in [name, 'Controle' if s['variant']=='control' else 'Notícias', s['cost'], brl(s['pnlBRL']), s['count'],f"{100*s['maxDD']:.2f}%", date(p['start'])])+'</tr>')
 notes.append('<p><strong>'+e(name)+':</strong> '+e(r['status'])+' no instante do snapshot; último resultado '+e(date(r['updatedAt']))+'. Cobertura: '+e(json.dumps(r.get('coverage',{}),ensure_ascii=False))+'.</p>')
encoded=json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
page='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trend Lab · G151 e notícias · snapshot</title><style>body{background:#101724;color:#e5edf8;font:16px/1.7 system-ui;max-width:1100px;margin:auto;padding:30px}a{color:#8acfff}h1{font-size:34px;line-height:1.2}p{color:#bdcce0}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:13px;text-align:left;border-bottom:1px solid #34445c}.scroll{overflow:auto}nav{display:flex;gap:20px;flex-wrap:wrap}aside{padding:15px;background:#1c2c42;border-radius:10px}code{overflow-wrap:anywhere}</style></head><body><nav><a href="../../README.md">Relatórios</a><a href="../../app/REPRODUCAO-GITHUB.md">Código e reprodução</a><a href="snapshot.json">Snapshot completo</a><a href="http://127.0.0.1:4173/pesquisa-genetica/experimento-noticias.html?strategy=g151">Painel local ao vivo</a></nav><h1>G151 e rompimento: notícias ajudam nas entradas?</h1>'''
page+='<aside><strong>Retrato estático: '+e(at)+'</strong><p>Este arquivo não acompanha o computador em tempo real. Todas as carteiras são simuladas. O snapshot não demonstra vantagem financeira.</p></aside><p>Quatro carteiras, R$1.000 simulados em cada uma; cada par repete custos base e elevados. Comparar com/sem notícias dentro da mesma estratégia. Os horários de início diferem.</p><div class="scroll"><table><thead><tr>'+''.join('<th>'+x+'</th>'for x in ['Estratégia','Carteira','Custos','Líquido','Operações','Drawdown','Início UTC'])+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'+''.join(notes)
page+='<h2>O que foi implementado</h2><p>G151 usa os dez Random Forests preservados, cinco sementes por família. Mantém sinais5m, contexto1h/4h, cortes de regime, limiares e prazos120/240min. O fechamento5m é observado antes de registrar entrada na abertura do minuto seguinte. Atrasos geram lacunas, nunca preenchimento retroativo.</p><p>As notícias podem vetar risco alto ou viés contrário. O veto não remove sinais contrários usados nas saídas. Informação futura, sem data, ausente ou expirada não vira decisão retroativa. Os pesos não são retreinados.</p><p>As duas rodadas têm registros independentes. O G151 tem30dias próprios. A janela de rompimento herdada é mais curta que o critério de30dias: permanece um piloto inconclusivo se não cumprir a amostra. Mesmo passar os critérios não autoriza dinheiro real.</p><h2>Validação</h2><p>213testesNode passaram no checkout completo. Os dez modelos reproduziram exatamente20scores arquivados, erro máximo0. Os16testes específicos também passaram no código exportado, sem datasets grandes. Conferir scores não prova lucro.</p><h2>Código ligado a este relatório</h2><ul>'
for title,file in [('G151 · coleta e protocolo','local-g151-news.mjs'),('G151 · cálculo e veto','g151-news-core.mjs'),('G151 · inferência sem treino','g151-inference.py'),('Rompimento · coleta','local-news-experiment.mjs'),('Notícias · validação e comparação','news-filter-core.mjs')]:page+='<li><a href="../../app/scripts/'+file+'">'+e(title)+'</a></li>'
page+='</ul><p><a href="../../app/source-manifest.json">Hashes de todo o código exportado</a> · manifestoSHA256 <code>'+data['codeManifestSHA256']+'</code>.</p><script type="application/json" id="snapshot-data">'+encoded+'</script></body></html>'
(out/'index.html').write_text(page)
print(json.dumps({'snapshotAt':at,'runs':list(runs),'path':str(out.relative_to(repo))}))
